import re
from typing import Dict

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    def expand_refs(key: str, section: Dict[str, str]) -> str:
        def replace_match(match: re.Match) -> str:
            ref = match.group(0)[2:]  # strip the leading ${ and }
            if ref.count(":"):
                section_name, key_name = ref.split(":", 1)
                try:
                    return section[section_name][key_name]
                except KeyError:
                    raise KeyError(f"missing key {section_name}:{key_name}")
            else:
                try:
                    return section[key]
                except KeyError:
                    raise KeyError(f"missing key {ref}")

        return re.sub(r"\${\s*([^}\s]+)\s*}", replace_match, key)

    lines = [line.strip() for line in text.splitlines() if not line.startswith(("#", ";")) and line.strip()]
    defaults = {}
    sections = {}

    for line in lines:
        if line.startswith("["):
            section_name = line[1:line.find("]")].strip()
            if section_name:
                sections[section_name] = {}
        else:
            if "=" in line or ":" in line:
                key, value = line.split(maxsplit=1)
                key, value = key.strip().lower(), value.strip()
                if key.endswith("#") or key.endswith(";"):
                    key, comment = key.rsplit(None, 1)
                else:
                    comment = None
                if key.endswith("\\"):
                    key = key[:-1].rstrip()
                    if not sections:
                        raise ValueError("key line before section header")
                    sections[section[key][-1]].update({key: value})
                else:
                    sections[section_name].update({key: expand_refs(value, sections[section_name])})
            elif line.startswith(" "):
                if not sections:
                    raise ValueError("key line before section header")
                sections[section[-1]].update({key: expand_refs(line, sections[section[-1]])})
            else:
                if not sections:
                    raise ValueError("key line before section header")
                sections[section[-1]].update({key: value})

    for section in sections:
        sections[section].update(defaults)

    return sections
