from collections import OrderedDict
from time import time

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def put(self, key, value):
        now = self.clock()
        if key in self.cache:
            self.cache.pop(key)
            self.cache[key] = (value, now)
        else:
            if len(self.cache) >= self.capacity:
                self._remove_expired()
                if len(self.cache) >= self.capacity:
                    self.cache.popitem(last=False)
            self.cache[key] = (value, now)
        self.stats["hits"] += 1

    def get(self, key, default=None):
        now = self.clock()
        if key in self.cache:
            value, expiry = self.cache[key]
            if now < expiry:
                self.stats["hits"] += 1
                self._move_to_end(key)
                return value
            else:
                self.stats["expirations"] += 1
                self._remove_expired()
                if key in self.cache:
                    self.stats["hits"] += 1
                    return self.cache.pop(key)[0]
        self.stats["misses"] += 1
        return default

    def _remove_expired(self):
        now = self.clock()
        keys_to_remove = [k for k, (_, expiry) in self.cache.items() if now >= expiry]
        for key in keys_to_remove:
            self.cache.pop(key)
            self.stats["expirations"] += 1

    def _move_to_end(self, key):
        value, expiry = self.cache.pop(key)
        self.cache[key] = (value, expiry)

    def __len__(self):
        now = self.clock()
        return sum(1 for k, (_, expiry) in self.cache.items() if now < expiry)

    def stats(self):
        return self.stats
