def parse_duration(s: str) -> int:
    from collections import OrderedDict

    if not s.strip():
        raise ValueError("Empty or blank string")

    time_map = OrderedDict([("h", 3600), ("m", 60), ("s", 1)])
    parts = [part.strip() for part in s.lower().split() if part.strip()]
    parsed_parts = []

    for part in parts:
        if len(part) < 2 or not part[:-1].isdigit() or part[-1] not in time_map:
            raise ValueError(f"Unknown unit or invalid format: {part}")
        parsed_parts.append(int(part[:-1]) * time_map[part[-1]])

    if len(parsed_parts) != len(time_map):
        raise ValueError("Repeating units or out of order units")

    return sum(parsed_parts)
