def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums.sort()
    result = []
    i = 0

    while i < len(nums):
        start = nums[i]
        while i + 1 < len(nums) and nums[i] + 1 == nums[i + 1]:
            i += 1
        end = nums[i]

        if end - start >= 2:
            result.append(f"{start}..{end}")
        else:
            result.extend(map(str, nums[i - (i > 0):i + 1]))

        i += 1

    return ",".join(result)
