import time

class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock=time.time):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = capacity
        self.last_time = clock()

    def allow(self, cost: float = 1) -> bool:
        current_time = self.clock()
        elapsed_time = current_time - self.last_time
        self.tokens = min(self.capacity, self.tokens + elapsed_time * self.refill_per_sec)
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

    @property
    def tokens(self):
        current_time = self.clock()
        elapsed_time = current_time - self.last_time
        self.last_time = current_time
        return min(self.capacity, self._tokens + elapsed_time * self.refill_per_sec)

    @tokens.setter
    def tokens(self, value):
        self._tokens = value
