from typing import List, Tuple
from decimal import Decimal, InvalidOperation

def top_customers(rows: List[dict], n: int) -> List[Tuple[str, float]]:
    from collections import defaultdict

    def parse_amount(amount: str) -> Decimal:
        try:
            return Decimal(amount.replace("$", "").replace(",", ""))
        except InvalidOperation:
            return Decimal(0)

    customer_totals = defaultdict(Decimal)

    for row in rows:
        name = row.get("customer").strip().lower()
        if not name or "amount" not in row:
            continue
        amount = row["amount"]
        parsed_amount = parse_amount(amount)
        if parsed_amount == 0:
            continue
        customer_totals[name] += parsed_amount

    top_customers = sorted(
        ((name, float(total)) for name, total in customer_totals.items()), 
        key=lambda x: (-x[1], x[0])
    )[:n]

    return top_customers
